runner.go.after:
package runner

import "fmt"

// Run stops at the first job that fails and returns its error.
func Run(jobs []func() error) error {
	for i, job := range jobs {
		if err := job(); err != nil {
			return fmt.Errorf("job %d failed: %w", i, err)
		}
	}
	return nil
}

