package search

import "strings"

func matches(title, query string) bool {
	lower := strings.ToLower(title) // lowered once, not once per word
	for _, word := range strings.Fields(strings.ToLower(query)) {
		if !strings.Contains(lower, word) {
			return false
		}
	}
	return true
}

